\TerribleTools\Admin::card('Find links in your content','01 / INDEX');echo '<p>Read the next 20 published posts or pages to build the link inventory. This does not change your content.</p>';UI::form('terrible-links','scan');UI::submit('Index next posts');echo '</section>';
\TerribleTools\Admin::card('Check their destinations','02 / CHECK');echo '<p>Check the next five links. A blocked or unreachable site stays “unverified”; only a confirmed missing page is marked broken.</p>';UI::form('terrible-links','check');UI::submit('Check next links');echo '</section></div>';
\TerribleTools\Admin::card('Link report');echo '<p class="tt-actions"><span class="tt-badge">'.($counts['broken']??0).' broken</span><span class="tt-badge">'.($counts['unverified']??0).' unverified</span><span class="tt-badge">'.($counts['pending']??0).' waiting</span></p>';
if (!$rows) echo '<p class="tt-empty">No links in the report yet. Start by indexing your content above.</p>';
else {echo '<div class="tt-table"><table class="widefat striped"><thead><tr><th>Page and link</th><th>Result</th><th>Repair</th></tr></thead><tbody>';foreach($rows as $r){echo '<tr><td><a href="'.esc_url(get_edit_post_link($r['post_id'])).'">'.esc_html(get_the_title($r['post_id'])).'</a><p>'.esc_html($r['url']).'</p></td><td>'.esc_html(ucfirst($r['status'])).($r['http_code']?' · HTTP '.(int)$r['http_code']:'').'</td><td><details><summary>Actions</summary>';UI::form('terrible-links','replace');echo '<input type="hidden" name="id" value="'.(int)$r['id'].'"><label>New URL<input name="target" type="url" required></label>';UI::submit('Replace in this page');UI::form('terrible-links','ignore');echo '<input type="hidden" name="id" value="'.(int)$r['id'].'">';UI::submit('Dismiss');echo '</details></td></tr>';}echo '</tbody></table></div>';}
echo '<p class="tt-help">Up to 500 report rows from a 5,000-reference inventory. Repairs preserve WordPress revisions. Dynamic content, CSS and external plugin stores are not indexed.</p><div class="tt-actions">';foreach(['restore'=>'Restore dismissed links','export'=>'Export report']as$op=>$label){UI::form('terrible-links',$op);UI::submit($label);}echo '</div></section></div>';
